import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';

const Navbar = () => {
  const [scrolled, setScrolled] = useState(false);
  const location = useLocation();
  const isHomePage = location.pathname === "/";

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Condition for Navbar coloring
  const navBg = (!isHomePage || scrolled) ? 'bg-emerald-950 shadow-xl py-3' : 'bg-transparent py-5';
  const textColor = 'text-white'; // Always white since we use Dark Green BG

  return (
    <nav className={`fixed top-0 w-full z-50 transition-all duration-300 ${navBg}`}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        <Link to="/" className="flex items-center space-x-2 group">
          <div className="w-10 h-10 bg-gradient-to-br from-emerald-400 to-teal-300 rounded-lg flex items-center justify-center text-emerald-950 font-bold text-xl group-hover:rotate-12 transition-transform shadow-lg">L</div>
          <span className={`text-2xl font-bold font-poppins tracking-tight ${textColor}`}>LawBridge</span>
        </Link>

        <div className="hidden md:flex space-x-8 items-center">
          <Link to="/" className={`font-medium hover:text-emerald-400 transition-colors ${textColor}`}>Home</Link>
          <Link to="/lawyers" className={`font-medium hover:text-emerald-400 transition-colors ${textColor}`}>Lawyers</Link>
          <Link to="/documents" className={`font-medium hover:text-emerald-400 transition-colors ${textColor}`}>Documents</Link>
          <Link to="/contact" className={`font-medium hover:text-emerald-400 transition-colors ${textColor}`}>Contact</Link>
          <Link to="/signup" className="bg-emerald-500 text-emerald-950 px-6 py-2.5 rounded-full font-bold hover:bg-emerald-400 transition-all shadow-lg hover:-translate-y-0.5">
            Get Started
          </Link>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
